"""N-Queens II — the same search, counting instead of materialising boards.

Time: O(n!)   Space: O(n)
"""


class Solution:
    def totalNQueens(self, n: int) -> int:
        cols, diag, anti = set(), set(), set()

        def walk(row: int) -> int:
            if row == n:
                return 1
            total = 0
            for col in range(n):
                if col in cols or row - col in diag or row + col in anti:
                    continue
                cols.add(col)
                diag.add(row - col)
                anti.add(row + col)
                total += walk(row + 1)
                cols.discard(col)
                diag.discard(row - col)
                anti.discard(row + col)
            return total

        return walk(0)
